create table if not exists public.theme_rules (id uuid primary key default gen_random_uuid(), user_id uuid not null default auth.uid() references auth.users(id) on delete cascade, theme_name text not null, rule_type text not null check (rule_type in ('required','allowed','forbidden','keyword')), value text not null, created_at timestamptz not null default now()); alter table public.theme_rules enable row level security; grant select,insert,update,delete on public.theme_rules to authenticated; create policy "own theme rules" on public.theme_rules for all using (user_id = auth.uid()) with check (user_id = auth.uid()); create index if not exists theme_rules_user_idx on public.theme_rules(user_id);